content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --secondary-color: #f3f4f6;
  --secondary-hover: #e5e7eb;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --bg-color: #f9fafb;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 40px 0;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--card-bg);
  padding: 16px 20px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--primary-color);
}

.stats {
  font-size: 0.9rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Flashcard 3D Animation styles */
.card-viewport {
  perspective: 1000px;
  width: 100%;
  height: 300px;
  cursor: pointer;
}

.flashcard {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.6s;
  transform-style: preserve-3d;
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

.flashcard.flipped {
  transform: rotateY(180deg);
}

.card-face {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 24px;
  border-radius: var(--radius);
  background: var(--card-bg);
  border: 1px solid var(--border-color);
}

.card-front {
  z-index: 2;
}

.card-back {
  transform: rotateY(180deg);
  background: #fdfcff;
}

.controls {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 20px;
}

.btn {
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: var(--text-main);
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.list-view {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: 450px;
  overflow-y: auto;
}

.word-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: #ffffff;
  transition: background-color 0.2s;
}

.word-item:hover {
  background-color: var(--bg-color);
}

.badge {
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 20px;
  background-color: var(--secondary-color);
  color: var(--text-muted);
}

.badge.mastered {
  background-color: #d1fae5;
  color: var(--success-color);
}

/* Responsive Design Improvements */
@media (max-width: 768px) {
  body {
    padding: 20px 0;
  }

  .app-container {
    max-width: 100%;
    padding: 16px;
  }

  .card-viewport {
    height: 280px;
  }
}

@media (max-width: 480px) {
  body {
    padding: 10px 0;
  }

  .app-container {
    padding: 12px;
  }

  .card-viewport {
    height: 240px;
  }

  .controls {
    flex-direction: column;
    gap: 8px;
  }

  .controls .btn {
    width: 100%;
  }

  .header {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }
}

/**
 * 英単語カードを表すインターフェース
 */
export interface WordCard {
  /** 一意の識別子 */
  id: string;
  /** 英語の単語 */
  english: string;
  /** 日本語の意味 */
  japanese: string;
  /** 例文 */
  example: string;
  /** カテゴリ */
  category: string;
  /** 習得済みかどうか */
  mastered: boolean;
  /** 難易度（将来の拡張用） */
  difficulty?: 'easy' | 'medium' | 'hard';
  /** 最終学習日時（将来の拡張用） */
  lastStudied?: string;
}

import { useState } from 'react';
import { WordCard } from '../types';

interface FlashcardProps {
  card: WordCard;
  onToggleMastered: (id: string) => void;
  onNext: () => void;
  onPrev: () => void;
}

export default function Flashcard({ card, onToggleMastered, onNext, onPrev }: FlashcardProps) {
  const [isFlipped, setIsFlipped] = useState(false);

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  return (
    <div>
      <div className="card-viewport" onClick={handleFlip}>
        <div className={`flashcard ${isFlipped ? 'flipped' : ''}`}>
          <div className="card-face card-front">
            <span className={`badge ${card.mastered ? 'mastered' : ''}`}>{card.category}</span>
            <h2>{card.english}</h2>
            <p>クリックして意味を確認</p>
          </div>
          <div className="card-face card-back">
            <span className={`badge ${card.mastered ? 'mastered' : ''}`}>{card.category}</span>
            <h3>{card.japanese}</h3>
            <p>"{card.example}"</p>
            <p>クリックして表に戻る</p>
          </div>
        </div>
      </div>

      <div className="controls">
        <button className="btn btn-secondary" onClick={(e) => { e.stopPropagation(); setIsFlipped(false); onPrev(); }}>
          前のカード
        </button>
        <button 
          className={`btn ${card.mastered ? 'btn-secondary' : 'btn-primary'}`} 
          onClick={(e) => { e.stopPropagation(); onToggleMastered(card.id); }}
        >
          {card.mastered ? '未習得に戻す' : '習得済みにする'}
        </button>
        <button className="btn btn-secondary" onClick={(e) => { e.stopPropagation(); setIsFlipped(false); onNext(); }}>
          次のカード
        </button>
      </div>
    </div>
  );
}

import { WordCard } from '../types';

interface CardListProps {
  cards: WordCard[];
  onToggleMastered: (id: string) => void;
  onSelectCard?: (index: number) => void;
}

export default function CardList({ cards = [], onToggleMastered, onSelectCard }: CardListProps) {
  return (
    <div className="list-view">
      <h3>単語一覧</h3>
      {cards.map((card, index) => (
        <div 
          key={card.id} 
          className="word-item" 
          onClick={() => onSelectCard?.(index)}
          onKeyDown={(e) => {
            if (onSelectCard && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault();
              onSelectCard(index);
            }
          }}
          tabIndex={onSelectCard ? 0 : undefined}
          role={onSelectCard ? 'button' : undefined}
        >
          <div>
            <div>
              <span>{card.english}</span>
              <span className={`badge ${card.mastered ? 'mastered' : ''}`}>{card.category}</span>
            </div>
            <div>{card.japanese}</div>
          </div>
          <button 
            className={`btn ${card.mastered ? 'btn-secondary' : 'btn-primary'}`} 
            onClick={(e) => {
              e.stopPropagation();
              onToggleMastered(card.id);
            }}
          >
            {card.mastered ? '習得済' : '未習得'}
          </button>
        </div>
      ))}
    </div>
  );
}

import { useState, useEffect } from 'react';
import './index.css';
import { WordCard } from './types';
import Flashcard from './components/Flashcard';
import CardList from './components/CardList';

const STORAGE_KEY = 'flashcard_app_cards';

const initialCards: WordCard[] = [
  { id: '1', english: 'Apple', japanese: 'りんご', example: 'I eat an apple every morning.', category: '果物', mastered: false },
  { id: '2', english: 'Book', japanese: '本', example: 'She is reading an interesting book.', category: '日常', mastered: true },
  { id: '3', english: 'Computer', japanese: 'コンピューター', example: 'He works on his computer all day.', category: 'テクノロジー', mastered: false },
  { id: '4', english: 'Dog', japanese: '犬', example: 'The dog is running in the park.', category: '動物', mastered: false },
  { id: '5', english: 'Elephant', japanese: '象', example: 'An elephant has a very long trunk.', category: '動物', mastered: false },
  { id: '6', english: 'Friend', japanese: '友達', example: 'A good friend is hard to find.', category: '人間関係', mastered: true },
  { id: '7', english: 'Guitar', japanese: 'ギター', example: 'He plays the guitar in a band.', category: '趣味', mastered: false },
  { id: '8', english: 'House', japanese: '家', example: 'They live in a large white house.', category: '日常', mastered: false },
  { id: '9', english: 'Island', japanese: '島', example: 'We spent our vacation on a tropical island.', category: '自然', mastered: false },
  { id: '10', english: 'Journey', japanese: '旅、旅行', example: 'Life is a journey, not a destination.', category: '日常', mastered: false },
];

export default function App() {
  const [cards, setCards] = useState<WordCard[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed;
        }
      }
    } catch (e) {
      console.error('Failed to load cards from localStorage:', e);
    }
    return initialCards;
  });

  const [currentIndex, setCurrentIndex] = useState(0);
  const [viewMode, setViewMode] = useState<'card' | 'list'>('card');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(cards));
    } catch (e) {
      console.error('Failed to save cards to localStorage:', e);
    }
  }, [cards]);

  useEffect(() => {
    if (cards.length > 0 && currentIndex >= cards.length) {
      setCurrentIndex(cards.length - 1);
    }
  }, [cards.length, currentIndex]);

  const masteredCount = cards.filter(c => c.mastered).length;

  const handleToggleMastered = (id: string) => {
    setCards(prev => prev.map(card => 
      card.id === id ? { ...card, mastered: !card.mastered } : card
    ));
  };

  const handleNext = () => {
    if (cards.length === 0) return;
    setCurrentIndex(prev => (prev + 1) % cards.length);
  };

  const handlePrev = () => {
    if (cards.length === 0) return;
    setCurrentIndex(prev => (prev - 1 + cards.length) % cards.length);
  };

  const handleSelectCard = (index: number) => {
    if (index >= 0 && index < cards.length) {
      setCurrentIndex(index);
      setViewMode('card');
    }
  };

  const currentCard = cards.length > 0 ? cards[currentIndex] || cards[0] : undefined;

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">英単語暗記カード</h1>
        <div className="stats">
          習得済み: {masteredCount} / {cards.length}
        </div>
      </header>

      <div style={{ display: 'flex', gap: '8px' }}>
        <button 
          className={`btn ${viewMode === 'card' ? 'btn-primary' : 'btn-secondary'}`}
          style={{ flex: 1 }}
          onClick={() => setViewMode('card')}
        >
          暗記カードモード
        </button>
        <button 
          className={`btn ${viewMode === 'list' ? 'btn-primary' : 'btn-secondary'}`}
          style={{ flex: 1 }}
          onClick={() => setViewMode('list')}
        >
          一覧表示モード
        </button>
      </div>

      {viewMode === 'card' && currentCard ? (
        <Flashcard 
          card={currentCard} 
          onToggleMastered={handleToggleMastered}
          onNext={handleNext}
          onPrev={handlePrev}
        />
      ) : viewMode === 'card' && !currentCard ? (
        <div style={{ textAlign: 'center', padding: '40px', background: 'var(--card-bg)', borderRadius: 'var(--radius)', boxShadow: 'var(--shadow)' }}>
          <p>表示できるカードがありません。</p>
        </div>
      ) : (
        <CardList 
          cards={cards} 
          onToggleMastered={handleToggleMastered}
          onSelectCard={handleSelectCard}
        />
      )}
    </div>
  );
}
